      SUBROUTINE ROTAT1(NM)CC     ROTATION OF FIRST-ORDER TRANSFER MATRIXCC ----------------------------------------------------------------------      INCLUDE 'ELM7B.CIN'      INCLUDE 'ELM10E.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'ELM20.CIN'      INCLUDE 'R.CIN'      INCLUDE 'RS.CIN'C----------------------------------------------------------------------      REAL            CODS(6), CODT(6)C      CSR = COS(TOTROT)      IF (ABS(CSR) .LT. 0.00001) CSR = 0.0      SNR = SIN(TOTROT)      IF (ABS(SNR) .LT. 0.00001 .AND. ABS(TOTRA) .GT. 0.01) SNR = 0.0CC     IDENTIFY MATRIX TO BE ROTATEDC      IF (NM .EQ. 0) THEN        IF (DCOV) THEN          DO 75 J = 1, 4   75     CODS(J) = COD(J)        ENDIF        IF (NORD1 .GE. 1) THEN          DO 80 JK = 1, 36   80     RSL(JK) = RL(JK)        ENDIF      ELSE        IF (DCOV) THEN          DO 85 J = 1, 4   85     CODS(J) = CODV(J)        ENDIF        IF (NORD1 .GE. 1) THEN          DO 90 JK = 1, 36   90     RSL(JK) = RVL(JK)        ENDIF      ENDIFCC     ROTATE AT ENTRANCEC  100 IF (NORD1 .GE. 1) THEN        DO 110 I = 1, 6        RT(I,1) = RS(I,1)*CSR - RS(I,3)*SNR        RT(I,3) = RS(I,1)*SNR + RS(I,3)*CSR        RT(I,2) = RS(I,2)*CSR - RS(I,4)*SNR        RT(I,4) = RS(I,2)*SNR + RS(I,4)*CSR        DO 110 J = 1, 4  110   RS(I,J) = RT(I,J)      ENDIFCC     ROTATE AT EXITC  200 IF (DCOV) THEN        CODT(1) = CODS(1)*CSR - CODS(3)*SNR        CODT(2) = CODS(2)*CSR - CODS(4)*SNR        CODT(3) = CODS(1)*SNR + CODS(3)*CSR        CODT(4) = CODS(2)*SNR + CODS(4)*CSR      ENDIFC  210 IF (NORD1 .GE. 1) THEN        DO 215 J = 1, 6        RT(1,J) = RS(1,J)*CSR - RS(3,J)*SNR        RT(3,J) = RS(1,J)*SNR + RS(3,J)*CSR        RT(2,J) = RS(2,J)*CSR - RS(4,J)*SNR        RT(4,J) = RS(2,J)*SNR + RS(4,J)*CSR  215   CONTINUE        DO 220 I = 1, 4        DO 220 J = 1, 6  220   RS(I,J) = RT(I,J)      ENDIFCC     REPLACE ROTATED MATRIXC  400 IF (NM .EQ. 0) THEN        IF (DCOV) THEN          DO 405 J = 1, 4  405     COD(J) = CODT(J)        ENDIF        IF (NORD1 .GE. 1) THEN          DO 410 JK = 1, 36  410     RL(JK) = RSL(JK)        ENDIF      ELSE        IF (DCOV) THEN          DO 455 J = 1, 4  455     CODV(J) = CODT(J)        ENDIF        IF (NORD1 .GE. 1) THEN          DO 460 JK = 1, 36  460     RVL(JK) = RSL(JK)        ENDIF      ENDIFC  500 IF (NORD1 .GE. 2) CALL ROTAT2(NM)      RETURN      END